<script setup lang="ts">
import { computed, ref } from "vue";
type Menu = { id: string; label: string; path: string; source: string; permission?: string; enabled: boolean }; const rows = ref<Menu[]>([{ id: 'dashboard', label: '仪表盘', path: '/dashboard', source: 'Core', permission: 'dashboard.view', enabled: true }, { id: 'resources', label: '资源管理', path: '/resource-center/resource-library', source: 'Core', permission: 'resource.read', enabled: true }, { id: 'storage', label: '存储', path: '/storage-center/storage-tiers', source: 'Core', permission: 'storage.read', enabled: true }]); const selected = ref<Menu | null>(rows.value[0]); const previewRole = ref('user'); const filtered = computed(() => rows.value);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">平台菜单</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">管理导航结构；Core 菜单受系统保护，不允许删除。</p></div><div class="flex gap-2"><el-select v-model="previewRole" class="w-36"><el-option label="普通用户" value="user"/><el-option label="管理员" value="admin"/></el-select><el-button>预览导航</el-button><el-button>恢复默认菜单</el-button></div></div><el-alert title="运行时菜单配置接口尚未接入；当前展示 Core 菜单安全预览。" type="info" show-icon :closable="false" class="mb-4"/><div class="grid grid-cols-1 md:grid-cols-3 gap-5"><el-card shadow="never"><template #header>子系统菜单树</template><el-tree :data="[{label:'Core',children:filtered.map(item => ({...item,label:`${item.label} · ${item.path}`}))},{label:'Plugin',children:[]},{label:'Custom',children:[]}]" node-key="label" default-expand-all @node-click="(node: any) => selected = rows.find(item => item.label === node.label) || selected"/></el-card><el-card shadow="never" class="md:col-span-2"><template #header><span>Menu Item Inspector</span></template><el-empty v-if="!selected" description="选择菜单项"/><el-form v-else label-position="top"><el-form-item label="Label"><el-input v-model="selected.label"/></el-form-item><el-form-item label="Destination"><el-input v-model="selected.path"/></el-form-item><el-form-item label="Source"><el-tag>{{ selected.source }}</el-tag></el-form-item><el-form-item label="Required Permission"><el-input v-model="selected.permission"/></el-form-item><el-form-item label="Visibility / Enabled"><el-switch v-model="selected.enabled"/></el-form-item><el-alert v-if="selected.source === 'Core'" title="Core Item 的 Permission Requirement 由后端声明，不能删除。" type="warning" show-icon/></el-form></el-card></div></main></template>
